using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalTests
{
    private readonly CalculatePayableTotal _useCase = new(new LoyaltyDiscountPolicy());

    [Fact]
    public void Gold_member_gets_five_percent_off_a_100_dollar_subtotal()
    {
        var payableTotalCents = _useCase.For(10_000, LoyaltyTier.Gold);

        Assert.Equal(9_500, payableTotalCents);
    }

    [Fact]
    public void Gold_member_gets_five_percent_off_a_200_dollar_subtotal()
    {
        var payableTotalCents = _useCase.For(20_000, LoyaltyTier.Gold);

        Assert.Equal(19_000, payableTotalCents);
    }

    [Fact]
    public void Gold_member_gets_five_percent_off_a_50_dollar_subtotal()
    {
        var payableTotalCents = _useCase.For(5_000, LoyaltyTier.Gold);

        Assert.Equal(4_750, payableTotalCents);
    }

    [Fact]
    public void Gold_member_pays_nothing_for_an_empty_basket()
    {
        var payableTotalCents = _useCase.For(0, LoyaltyTier.Gold);

        Assert.Equal(0, payableTotalCents);
    }
}
